set-variable.value:
@{
      var policy = ((IResponse)context.Variables["policyResponse"]).Body.As<JObject>(preserveContent: true);
      var claims = ((IResponse)context.Variables["claimsResponse"]).Body.As<JObject>(preserveContent: true);
      var id = context.Request.MatchedParameters["policyId"];
      return policy.Count == 4
        && (string)policy["policyId"] == id
        && (string)policy["status"] == "Active"
        && ((string)policy["product"] == "Home" || (string)policy["product"] == "Motor")
        && ((string)policy["riskCategory"] == "Standard" || (string)policy["riskCategory"] == "Elevated")
        && claims.Count == 4
        && (string)claims["policyId"] == id
        && claims["openClaimCount"] != null
        && claims["openClaimCount"].Type == JTokenType.Integer
        && (int)claims["openClaimCount"] >= 0
        && claims["totalIncurred"] != null
        && (claims["totalIncurred"].Type == JTokenType.Integer || claims["totalIncurred"].Type == JTokenType.Float)
        && (decimal)claims["totalIncurred"] >= 0
        && (string)claims["currency"] == "NZD";
    }
